@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/geist-mono";

/* Light: cream pages (#f3f1e0) with #212121 text, bronze-tan bands (#ad9069, secondary) and
   signal yellow (#ffcc00) for buy buttons, the active tab and stars. */
:root {
  --background: oklch(0.955 0.023 101.3);
  --foreground: oklch(0.248 0 0);
  --card: oklch(0.931 0.027 99.9);
  --card-foreground: oklch(0.248 0 0);
  --popover: oklch(0.985 0.01 100);
  --popover-foreground: oklch(0.248 0 0);
  --primary: oklch(0.865 0.177 90.4);
  --primary-foreground: oklch(0.248 0 0);
  --secondary: oklch(0.67 0.064 74.6);
  --secondary-foreground: oklch(0.248 0 0);
  --muted: oklch(0.91 0.031 98.9);
  --muted-foreground: oklch(0.561 0.017 98.5);
  --accent: oklch(0.879 0.035 98.1);
  --accent-foreground: oklch(0.248 0 0);
  --destructive: oklch(0.58 0.2 28);
  --destructive-foreground: oklch(0.985 0.01 100);
  --border: oklch(0.248 0 0 / 15%);
  --input: oklch(0.248 0 0 / 30%);
  --ring: oklch(0.865 0.177 90.4);
  --highlight: oklch(0.865 0.177 90.4);
  --highlight-foreground: oklch(0.248 0 0);
  --glow: oklch(0.67 0.064 74.6);
  --chart-1: oklch(0.865 0.177 90.4);
  --chart-2: oklch(0.67 0.064 74.6);
  --chart-3: oklch(0.248 0 0);
  --chart-4: oklch(0.515 0.053 73.6);
  --chart-5: oklch(0.6 0 0);
  --sidebar: oklch(0.931 0.027 99.9);
  --sidebar-foreground: oklch(0.248 0 0);
  --sidebar-primary: oklch(0.865 0.177 90.4);
  --sidebar-primary-foreground: oklch(0.248 0 0);
  --sidebar-accent: oklch(0.879 0.035 98.1);
  --sidebar-accent-foreground: oklch(0.248 0 0);
  --sidebar-border: oklch(0.248 0 0 / 15%);
  --sidebar-ring: oklch(0.865 0.177 90.4);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 5px;
  --page-width: 90rem;
  --page-gutter: 1.3rem;
  --section-y: 4.5rem;
}

/* The original's 40px gutters and ~120px band padding on wide screens. */
@media (min-width: 1024px) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 7.5rem;
  }
}

/* Dark: the #212121 bands with cream text, near-black (#111) behind the hero video, #2c2c2c
   media surfaces, cream glass at 15-20% for chrome; tan deepens to bronze. */
.dark {
  --background: oklch(0.248 0 0);
  --foreground: oklch(0.955 0.023 101.3);
  --card: oklch(0.178 0 0);
  --card-foreground: oklch(0.955 0.023 101.3);
  --popover: oklch(0.285 0 0);
  --popover-foreground: oklch(0.955 0.023 101.3);
  --primary: oklch(0.865 0.177 90.4);
  --primary-foreground: oklch(0.248 0 0);
  --secondary: oklch(0.319 0.024 74.7);
  --secondary-foreground: oklch(0.955 0.023 101.3);
  --muted: oklch(0.293 0 0);
  --muted-foreground: oklch(0.678 0.017 99.1);
  --accent: oklch(0.955 0.023 101.3 / 15%);
  --accent-foreground: oklch(0.955 0.023 101.3);
  --destructive: oklch(0.68 0.19 25);
  --destructive-foreground: oklch(0.248 0 0);
  --border: oklch(0.955 0.023 101.3 / 20%);
  --input: oklch(0.955 0.023 101.3 / 20%);
  --ring: oklch(0.865 0.177 90.4);
  --highlight: oklch(0.865 0.177 90.4);
  --highlight-foreground: oklch(0.248 0 0);
  --glow: oklch(0.67 0.064 74.6);
  --chart-1: oklch(0.865 0.177 90.4);
  --chart-2: oklch(0.67 0.064 74.6);
  --chart-3: oklch(0.955 0.023 101.3);
  --chart-4: oklch(0.515 0.053 73.6);
  --chart-5: oklch(0.6 0 0);
  --sidebar: oklch(0.178 0 0);
  --sidebar-foreground: oklch(0.955 0.023 101.3);
  --sidebar-primary: oklch(0.865 0.177 90.4);
  --sidebar-primary-foreground: oklch(0.248 0 0);
  --sidebar-accent: oklch(0.293 0 0);
  --sidebar-accent-foreground: oklch(0.955 0.023 101.3);
  --sidebar-border: oklch(0.955 0.023 101.3 / 20%);
  --sidebar-ring: oklch(0.865 0.177 90.4);
}
